#!/usr/bin/env bash
# Factory gate (generated by `factory render`; the steps live in .factory/config/factory.yaml).
#   .factory/gate.sh <worktree> <base-branch> <out-dir>
# Writes <out-dir>/gate.log and gate.json; exit 0 only when every gate step passes.
set -uo pipefail
[[ $# -eq 3 ]] || { echo "usage: $0 <worktree> <base-branch> <out-dir>" >&2; exit 2; }
DIR="$(cd "$(dirname "${BASH_SOURCE[0]}")" && pwd)"
exec python3 "$DIR/factory.py" --json gate-run "$1" "$2" "$3"
